const assert = require('node:assert/strict');
const fs = require('node:fs');
const events = require('../data/events.json');
const people = require('../data/characters.json');
const event = id => events.find(e => e.id === id);
assert.ok(event('E389-001').characters.includes('P07-G03'));
assert.equal(event('E389-001').character_presence['P07-G03'], 'mentioned');
assert.match(event('E389-004').title, /誕生日.*先祝い/);
assert.doesNotMatch(event('E389-003').description, /第9王子が拘束/);
assert.match(event('E389-011').description, /第9王子ハルケンブルグが拘束/);
assert.match(event('E389-011').description, /拘束そのものの場面は描かれない/);
assert.ok(event('E389-011').characters.includes('JUD-004'));
assert.ok(event('E389-011').characters.includes('JUD-005'));
assert.doesNotMatch(event('E389-006').description + event('E389-006').title, /カミーラが.*早く死にたい/);
assert.equal(event('E402-007').time_estimate, '07:55');
assert.equal(event('E402-007').time_start, null);
assert.match(event('E403-014').description, /^カイザルと/);
for (const id of ['P02', 'P03', 'P05', 'P06']) assert.ok(event('E403-015').characters.includes(id));
const pickup = event('E404-009');
assert.equal(pickup.day, 1); assert.equal(pickup.chapter, 404);
assert.equal(pickup.date_certainty, 'confirmed'); assert.equal(pickup.time_start, null);
assert.ok(pickup.characters.includes('P01-P11'));
assert.notEqual(pickup.series, event('E404-101').series);
const gyatome = people.find(p => p.id === 'EII-U02');
assert.equal(gyatome.name, 'ギャトーム'); assert.equal(gyatome.identity_status, 'provisional');
assert.match(gyatome.role, /元当たり屋/); assert.match(gyatome.notes, /メモに基づく暫定同定/);
assert.equal(people.filter(p => p.name === 'ギャトーム').length, 1);
const theory = fs.readFileSync('theories/Q005/index.html', 'utf8');
assert.match(theory, /ルズールス/); assert.match(theory, /消耗の原因を比較/);
assert.match(theory, /別の術者/); assert.match(theory, /酷使/);
console.log('PASS: new memo corrections, reported arrest split, provisional identity, letter readers, explicit approximate clock and first coin pickup');
